import {createRequire} from 'node:module';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface SchemaError {
  instancePath?: string;
  dataPath?: string;
  keyword: string;
  params: Record<string, unknown>;
  message?: string;
}

interface CompiledSchemaValidator {
  (input: unknown): boolean;
  errors?: SchemaError[] | null;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validateInput: CompiledSchemaValidator;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly dynamicSchemaCache = new WeakMap<Record<string, unknown>, CompiledSchemaValidator>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validateInput = compileSchema(resolved.name, resolved.inputSchema);
    if (typeof definition === 'function') {
      this.dynamicSchemaCache.set(resolved.inputSchema, validateInput);
    }
    this.tools.set(resolved.name, {definitionSource: definition, execute, validateInput});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against the tool's inputSchema (see specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validateInput = resolveValidator(tool, this.dynamicSchemaCache);
    if (!validateInput(input)) {
      const rejection = formatValidationErrors(name, validateInput.errors);
      log.warn('tool', 'input validation failed', {name, reason: rejection});
      return {result: rejection};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

function resolveValidator(
  tool: StoredTool,
  dynamicSchemaCache: WeakMap<Record<string, unknown>, CompiledSchemaValidator>
): CompiledSchemaValidator {
  if (typeof tool.definitionSource !== 'function') {
    return tool.validateInput;
  }
  const resolved = tool.definitionSource();
  const cached = dynamicSchemaCache.get(resolved.inputSchema);
  if (cached) {
    return cached;
  }
  const compiled = compileSchema(resolved.name, resolved.inputSchema);
  dynamicSchemaCache.set(resolved.inputSchema, compiled);
  return compiled;
}

interface AjvCompiler {
  compile(schema: Record<string, unknown>): CompiledSchemaValidator;
}

type AjvConstructor = new (options?: Record<string, unknown>) => AjvCompiler;

const nodeRequire = createRequire(import.meta.url);
const Ajv = nodeRequire('ajv') as AjvConstructor;
const ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});

function compileSchema(toolName: string, schema: Record<string, unknown>): CompiledSchemaValidator {
  try {
    return ajv.compile(schema);
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${detail}`, {cause: error});
  }
}

function formatValidationErrors(toolName: string, errors?: SchemaError[] | null): string {
  if (!errors || errors.length === 0) {
    return `Invalid input for tool "${toolName}"`;
  }
  const details = errors.map(formatSingleError);
  return `Invalid input for tool "${toolName}": ${details.join('; ')}`;
}

function formatSingleError(error: SchemaError): string {
  const path = formatFieldPath(error);
  if (error.keyword === 'required') {
    return `${path} is required`;
  }
  if (error.keyword === 'type') {
    const expectedType = formatExpectedType(error.params.type);
    return `${path} must be ${expectedType}`;
  }
  if (error.keyword === 'enum') {
    const {allowedValues} = error.params;
    if (!Array.isArray(allowedValues)) {
      return `${path} failed enum validation`;
    }
    const allowed = allowedValues.map(entry => JSON.stringify(entry));
    return `${path} must be one of: ${allowed.join(', ')}`;
  }
  return error.message ? `${path} ${error.message}` : `${path} failed ${error.keyword} validation`;
}

function formatFieldPath(error: SchemaError): string {
  const rawPath = error.instancePath ?? error.dataPath ?? '';
  const stripped = rawPath.replace(/^[./]+/, '');
  const normalized = stripped.replace(/\//g, '.');
  if (error.keyword === 'required') {
    const missing = String(error.params.missingProperty ?? '');
    return normalized ? `${normalized}.${missing}` : missing;
  }
  return normalized || 'input';
}

function formatExpectedType(typeParam: unknown): string {
  if (Array.isArray(typeParam)) {
    return typeParam.map(String).join(' or ');
  }
  return typeof typeParam === 'string' ? typeParam : 'valid type';
}

