import {ToolRegistry} from './registry.js';
import {setLogger} from '../../shared/logger.js';
import type {Logger} from '../../shared/logger.js';
import type {ToolDefinition} from '../../types/ai.js';

function captureLogs(): string[] {
  const entries: string[] = [];
  const append = (category: string, message: string, fields?: Record<string, unknown>) => {
    entries.push(JSON.stringify({category, message, fields}));
  };
  const logger: Logger = {debug: append, info: append, warn: append, error: append};
  setLogger(logger);
  return entries;
}

describe('ToolRegistry', () => {
  afterEach(() => {
    setLogger(undefined);
  });

  it('throws at registration time naming the tool for an uncompilable schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Tool with an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {
              query: {type: 'not-a-json-schema-type'},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('rejects input missing a required property and leaves the executor uncalled', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'forecast',
        description: 'Fetch forecast',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );

    const response = await registry.execute('forecast', {});

    expect({
      executorCalls,
      namesLocation: response.result.includes('location'),
      mentionsRequired: /required/i.test(response.result),
    }).toEqual({
      executorCalls: 0,
      namesLocation: true,
      mentionsRequired: true,
    });
  });

  it('passes valid input with unlisted extra properties unchanged without adding defaults or coercing', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    let receivedInput: Record<string, unknown> | undefined;
    registry.register(
      {
        name: 'record_reading',
        description: 'Record sensor reading',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
            count: {type: 'number'},
            units: {type: 'string', default: 'celsius'},
          },
          required: ['location'],
        },
      },
      async input => {
        executorCalls += 1;
        receivedInput = input;
        return 'recorded';
      }
    );

    const response = await registry.execute('record_reading', {
      location: 'Oslo',
      count: 7,
      extraTag: 'sensor-a',
    });

    expect({
      executorCalls,
      receivedInput,
      result: response.result,
    }).toEqual({
      executorCalls: 1,
      receivedInput: {location: 'Oslo', count: 7, extraTag: 'sensor-a'},
      result: 'recorded',
    });
  });

  it('rejects a wrong-typed property naming the field path and expected type without leaking the value', async () => {
    const logs = captureLogs();
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'account_lookup',
        description: 'Look up account',
        inputSchema: {
          type: 'object',
          properties: {
            account: {
              type: 'object',
              properties: {code: {type: 'string'}},
              required: ['code'],
            },
          },
          required: ['account'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'ok';
      }
    );

    const response = await registry.execute('account_lookup', {account: {code: 987654321}});

    expect({
      executorCalls,
      mentionsPath: response.result.includes('account.code'),
      mentionsType: response.result.includes('string'),
      leaksResult: response.result.includes('987654321'),
      leaksLogs: logs.some(line => line.includes('987654321')),
    }).toEqual({
      executorCalls: 0,
      mentionsPath: true,
      mentionsType: true,
      leaksResult: false,
      leaksLogs: false,
    });
  });

  it('rejects a value outside the declared enum without leaking the offending value', async () => {
    const logs = captureLogs();
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'temperature_unit',
        description: 'Convert temperature',
        inputSchema: {
          type: 'object',
          properties: {
            units: {type: 'string', enum: ['celsius', 'fahrenheit']},
          },
          required: ['units'],
        },
      },
      async () => 'ok'
    );

    const response = await registry.execute('temperature_unit', {units: 'kelvin-secret-value'});

    expect({
      mentionsField: response.result.includes('units'),
      mentionsAllowed: response.result.includes('celsius') && response.result.includes('fahrenheit'),
      leaksResult: response.result.includes('kelvin-secret-value'),
      leaksLogs: logs.some(line => line.includes('kelvin-secret-value')),
    }).toEqual({
      mentionsField: true,
      mentionsAllowed: true,
      leaksResult: false,
      leaksLogs: false,
    });
  });

  it('validates a function-valued tool definition against the schema current at each execute call', async () => {
    const registry = new ToolRegistry();
    const citySchema = {
      type: 'object',
      properties: {city: {type: 'string'}},
      required: ['city'],
    };
    const postalSchema = {
      type: 'object',
      properties: {postalCode: {type: 'number'}},
      required: ['postalCode'],
    };
    let activeSchema: Record<string, unknown> = citySchema;

    registry.register(
      () => ({
        name: 'dynamic_geo',
        description: 'Dynamic geo lookup',
        inputSchema: activeSchema,
      }),
      async input => JSON.stringify(input)
    );

    const first = await registry.execute('dynamic_geo', {city: 'Rome'});
    activeSchema = postalSchema;
    const staleAttempt = await registry.execute('dynamic_geo', {city: 'Rome'});
    const updatedAttempt = await registry.execute('dynamic_geo', {postalCode: 10115});

    expect({
      firstResult: first.result,
      rejectedAgainstNewSchema:
        staleAttempt.result.includes('postalCode') && /required/i.test(staleAttempt.result),
      updatedResult: updatedAttempt.result,
    }).toEqual({
      firstResult: '{"city":"Rome"}',
      rejectedAgainstNewSchema: true,
      updatedResult: '{"postalCode":10115}',
    });
  });

  it('compiles a static tool schema once across ten execute calls', async () => {
    const registry = new ToolRegistry();
    let schemaReads = 0;
    let executorCalls = 0;
    const staticSchema = {
